CASES=[
('בג"ץ 5016/96 חורב נ׳ שר התחבורה, פ"ד נא(4) 1 (1997)','בקשה לסגור את רחוב בר-אילן בירושלים בשבת בשל רגשות דתיים.','פגיעה ברגשות דתיים מצדיקה הגבלה רק אם היא חמורה, קשה ורצינית ובכפוף למידתיות; החלטת הסגירה בשעות התפילה בוטלה והוחזרה לשר, כי לא ניתן משקל מספיק לתושבים החילוניים. למבחן: דת מול חופש תנועה.'),
('בג"ץ 953/01 סולודקין נ׳ עיריית בית שמש (2004)','חוקי עזר של עירייה המגבילים מכירת בשר חזיר.','לרשות מקומית סמכות להגביל, אך יש לאזן מידתית לפי אופי האזור. למבחן: סמכות רשות מקומית ומידתיות מקומית.'),
('בג"ץ 143/62 פונק-שלזינגר נ׳ שר הפנים (1963)','רישום נישואין אזרחיים שנערכו בחו"ל במרשם האוכלוסין.','פקיד הרישום רושם את עובדת הנישואין בלי לבחון את תוקפם. למבחן: פתרון חלקי לחופש מדת בנישואין.'),
('חוק שיפוט בתי דין רבניים (נישואין וגירושין), התשי"ג-1953','הסדר שיפוט בנישואין וגירושין של יהודים.','נישואין וגירושין של יהודים בישראל לפי דין תורה בבית דין רבני. למבחן: מקור הפגיעה האפשרית בחופש מדת.')
]
QS=[
Q('מהו "החופש מדת"?','הזכות שלא לכפות על אדם נורמה דתית שאינה שלו',['הזכות לפולחן','זכות הקניין','זכות הביטוי'],'החופש מדת הוא הצד המשלים לחופש הדת: זכותו של אדם שלא תיכפה עליו נורמה דתית שאינה שלו. פולחן הוא חופש הדת עצמו, וזכות הקניין והביטוי הן זכויות אחרות.'),
Q('מהו המעמד החוקתי של חופש הדת?','נגזר מכבוד האדם, לא מנוי',['מנוי בס׳ 2','אינו זכות חוקתית','מנוי בחוק העיסוק'],'חופש הדת אינו מנוי בחוק היסוד אלא נגזר מכבוד האדם והאוטונומיה. ס׳ 2 עוסק בחיים, גוף וכבוד, וחוק יסוד: חופש העיסוק אינו מקור לחופש הדת. הטענה שאין לו מעמד חוקתי שגויה.'),
Q('איזה חוק מסדיר נישואין וגירושין של יהודים?','חוק שיפוט בתי דין רבניים התשי"ג-1953',['חוק השבות','חוק העונשין','חוק הכנסת'],'נישואין וגירושין של יהודים בישראל מוסדרים בחוק שיפוט בתי דין רבניים (נישואין וגירושין), התשי"ג-1953, המקנה סמכות לבתי הדין הרבניים. חוק השבות, חוק העונשין וחוק הכנסת אינם מסדירים נישואין.'),
Q('מה השלכת החוק הזה על חופש מדת?','אין נישואים אזרחיים בישראל',['נישואים אזרחיים מותרים','אין נישואים כלל','חובת נישואים'],'לפי החוק נישואי יהודים נערכים בבית דין רבני, ולכן אין בישראל נישואין אזרחיים. זו פגיעה אפשרית בחופש מדת, והטענה שנישואים אזרחיים מותרים בישראל אינה נכונה.'),
Q('מה נקבע בפונק-שלזינגר?','רישום נישואין אזרחיים מחו"ל במרשם בלי לבחון תוקפם',['איסור רישום','חובת נישואים דתיים','הכרה מלאה בנישואים אזרחיים'],'בעניין פונק-שלזינגר נקבע שפקיד הרישום רושם עובדה של נישואין אזרחיים שנערכו בחו"ל, בלי לבחון את תוקפם ההלכתי. אין זו הכרה מלאה בנישואין אזרחיים, ואין חובה להינשא דתית או איסור רישום.'),
Q('חורב עסק ב:','סגירת רחוב בשבת בשל רגשות דתיים',['בשר חזיר','נישואין','גיוס'],'בעניין חורב נדונה בקשה לסגור רחוב בשבת בשל פגיעה ברגשות דתיים ובקדושת השבת, מול חופש התנועה של אחרים. גיוס, נישואין ובשר חזיר הם נושאים של פרשות אחרות, כמו סולודקין.'),
Q('איזה רחוב נדון בחורב?','בר-אילן',['יפו','דיזנגוף','הרצל'],'חורב עסק ברחוב בר-אילן בירושלים, שבו התנהל עימות בין הרצון לשמור על קדושת השבת לבין חופש התנועה. רחובות הרצל, דיזנגוף ויפו אינם הרחוב שנדון בפרשה.'),
Q('איזה סוג פגיעה ברגשות דתיים מצדיק הגבלה?','חמורה, קשה ורצינית',['כל פגיעה','פגיעה קלה','פגיעה תיאורטית'],'לפי חורב, פגיעה ברגשות דתיים מצדיקה הגבלה רק אם היא חמורה, קשה ורצינית. פגיעה תיאורטית או קלה, וגם כל פגיעה באשר היא, אינן מספיקות להגבלת זכויות אחרות.'),
Q('מה עלה בגורל החלטת הסגירה של רחוב בר-אילן בשעות התפילה בחורב?','בוטלה והוחזרה לשר, כי לא נשקלו די צורכיהם של התושבים החילוניים',['אושרה ללא שינוי','אושרה כסגירה לצמיתות','נקבע שרגשות דתיים אינם שיקול כלל'],'בחורב בוטלה החלטת הסגירה והוחזרה לשר, בעיקר כי לא ניתן משקל מספיק לתושבים החילוניים. בית המשפט לא שלל שיקול של רגשות דתיים, אלא דרש פגיעה חמורה, קשה ורצינית ובחינת מידתיות.'),
Q('סולודקין עסק ב:','חוקי עזר המגבילים בשר חזיר',['חופש ביטוי','שוויון','גיוס'],'בעניין סולודקין נדונו חוקי עזר של עירייה שהגבילו מכירת בשר חזיר, שאלה של סמכות רשות מקומית ושל איזון בין חופש מדת וחופש עיסוק. שוויון, חופש ביטוי וגיוס אינם נושא הפרשה.'),
Q('מי חוקק את חוקי העזר בסולודקין?','עיריית בית שמש',['הכנסת','הממשלה','בג"ץ'],'חוקי העזר שנדונו בסולודקין נחקקו בידי עיריית בית שמש, כרשות מקומית שהוסמכה לכך. הכנסת והממשלה אינן מחוקקות חוקי עזר, ובג"ץ הוא שבחן את תוקפם ולא חוקק אותם.'),
Q('מהי ההלכה בסולודקין?','לרשות מקומית סמכות להגביל, אך באיזון מידתי לפי אזור',['אין סמכות','סמכות מוחלטת','הגבלה גורפת מותרת'],'בסולודקין נקבע שלרשות מקומית סמכות להגביל מכירת חזיר, אך עליה לאזן בין אופי האזור לבין חופש עיסוק וחופש מדת. סמכות מוחלטת או הגבלה גורפת מתעלמות ממידתיות, וטענה שאין סמכות שוללת את הסמכות שהוכרה.'),
Q('איזה חוק אוסר גידול חזיר?','חוק איסור גידול חזיר התשכ"ב-1962',['חוק השבות','חוק החוזים','חוק הכנסת'],'חוק איסור גידול חזיר, התשכ"ב-1962, אוסר גידול חזירים בישראל. חוק הכנסת, חוק החוזים וחוק השבות אינם עוסקים בגידול חזיר, ולכן אינם התשובה.'),
Q('איזה חוק מסדיר מנוחה שבועית?','חוק שעות עבודה ומנוחה התשי"א-1951',['חוק הנישואין','חוק העונשין','חוק הגנת הפרטיות'],'חוק שעות עבודה ומנוחה, התשי"א-1951, מסדיר את המנוחה השבועית, ובכך את שבת כיום מנוחה. חוק הגנת הפרטיות, חוק העונשין וחוק הנישואין אינם מסדירים מנוחה שבועית.'),
Q('מהי הצדקה חיצונית להגבלה?','סדר ציבורי או ערכים אזרחיים',['חובה הלכתית','רצון הרב','מסורת משפחה'],'הצדקה חיצונית להגבלה נשענת על שיקולים של המדינה, כמו סדר ציבורי וערכים אזרחיים, ולא על חובה הלכתית פנימית. חובה הלכתית, מסורת משפחה ורצון הרב הם שיקולים דתיים פנימיים שאינם מצדיקים הגבלה של המדינה.'),
Q('מה ההבדל בין חופש הדת לחופש מדת?','חופש הדת מגן על אמונה ופולחן, וחופש מדת מגן מפני כפיית נורמה דתית',['חופש הדת חל על אזרחים בלבד, וחופש מדת על תושבים בלבד','אין הבדל, שניהם מתארים אותה זכות','חופש הדת מנוי בחוק היסוד וחופש מדת אינו נגזר מכבוד'],'חופש הדת מגן על קיום אמונה ופולחן, ואילו החופש מדת מגן על אדם מפני כפיית נורמה דתית שאינה שלו. הם שני צדדים של אותו עניין, ולכן לא נכון שאין ביניהם הבדל או שרק האחד נגזר מכבוד.'),
Q('איזה עיקרון חל על הגבלת זכות?','מידתיות',['חזקה','שיהוי','בשלות'],'מידתיות היא העיקרון המרכזי בהגבלת זכות: שימוש באמצעי הפוגע פחות והולם את התכלית. בשלות עוסקת בעיתוי עתירה, שיהוי באיחור, וחזקה היא כלל ראייתי, ולכן אין בהם כדי לבחון הגבלת זכויות.'),
Q('מי יכול להגביל זכות יסוד?','חוק או הסמכה מפורשת',['פקיד','נוהג','החלטת אזרח'],'זכות יסוד ניתנת להגבלה רק בחוק או מכוח הסמכה מפורשת בחוק. נוהג, החלטת פקיד או החלטת אזרח אינם מקור סמכות להגביל זכות יסוד, ולכן אינם תשובה נכונה.'),
Q('מהו חופש הדת?','זכות להאמין ולקיים פולחן',['זכות לאי-אמונה בלבד','זכות לרכוש','זכות לחיות בחו"ל'],'חופש הדת כולל את הזכות להאמין ולקיים פולחן לפי אמונתו של אדם, ללא כפייה. זכות לרכוש או לחיות בחו"ל היא זכות אחרת, והגבלתה לאי-אמונה בלבד מתעלמת מצד האמונה והפולחן.'),
Q('איזו קביעה אינה נכונה?','חורב קבע שרגשות דתיים אינם יכולים לשמש שיקול כלל',['חורב עסק בבר-אילן','חורב דורש מידתיות','חורב עסק ברגשות דתיים'],'בחורב הוכר שרגשות דתיים הם אינטרס שיכול להצדיק הגבלה אם הפגיעה בהם חמורה, קשה ורצינית ובכפוף למידתיות, ולכן הקביעה שאין להתחשב בהם כלל אינה נכונה. שלוש האפשרויות האחרות נכונות: מידתיות, רחוב בר-אילן ורגשות דתיים.'),
]
